-- REVIEW ONLY. Preparation approval does not authorize production SQL.
CREATE TABLE IF NOT EXISTS nba_history_versions(source TEXT,sha TEXT,body TEXT,bytes INTEGER,PRIMARY KEY(source,sha));

CREATE TABLE IF NOT EXISTS nba_history_checks(source TEXT PRIMARY KEY,sha TEXT,verified TEXT);

CREATE TABLE IF NOT EXISTS nba_bootstrap_events(event TEXT PRIMARY KEY,run TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN ('manifest','publish','rollback','consume')),body TEXT NOT NULL CHECK(json_valid(body)));

CREATE TRIGGER IF NOT EXISTS nba_bootstrap_events_no_replace BEFORE INSERT ON nba_bootstrap_events WHEN EXISTS(SELECT 1 FROM nba_bootstrap_events WHERE event=NEW.event) BEGIN SELECT RAISE(ABORT,'bootstrap_journal_immutable'); END;

CREATE TRIGGER IF NOT EXISTS nba_bootstrap_events_no_update BEFORE UPDATE ON nba_bootstrap_events BEGIN SELECT RAISE(ABORT,'bootstrap_journal_immutable'); END;

CREATE TRIGGER IF NOT EXISTS nba_bootstrap_events_no_delete BEFORE DELETE ON nba_bootstrap_events BEGIN SELECT RAISE(ABORT,'bootstrap_journal_immutable'); END;

CREATE TRIGGER IF NOT EXISTS nba_bootstrap_manifest_guard BEFORE INSERT ON nba_bootstrap_events WHEN NEW.kind='manifest' BEGIN SELECT CASE WHEN NEW.event!='manifest:'||NEW.run OR json_extract(NEW.body,'$.run')!=NEW.run OR json_extract(NEW.body,'$.consumerInactive')!=1 THEN RAISE(ABORT,'bootstrap_manifest_invalid') END; END;

CREATE TRIGGER IF NOT EXISTS nba_bootstrap_publish_guard BEFORE INSERT ON nba_bootstrap_events WHEN NEW.kind='publish' BEGIN
 SELECT CASE WHEN NEW.event!='publish:'||NEW.run OR NEW.body!='{}' OR (SELECT body FROM nba_bootstrap_events WHERE event='manifest:'||NEW.run AND kind='manifest') IS NULL OR EXISTS(SELECT 1 FROM nba_bootstrap_events WHERE run=NEW.run AND kind IN ('rollback','consume')) THEN RAISE(ABORT,'bootstrap_publish_invalid') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM json_each(json_extract((SELECT body FROM nba_bootstrap_events WHERE event='manifest:'||NEW.run AND kind='manifest'),'$.versions')) j WHERE NOT EXISTS(SELECT 1 FROM nba_history_versions v WHERE v.source=json_extract(j.value,'$.source') AND v.sha=json_extract(j.value,'$.sha') AND v.body=json_extract(j.value,'$.body') AND v.bytes=json_extract(j.value,'$.bytes'))) OR EXISTS(SELECT 1 FROM nba_history_versions v WHERE v.source IN(SELECT value FROM json_each(json_extract((SELECT body FROM nba_bootstrap_events WHERE event='manifest:'||NEW.run AND kind='manifest'),'$.sources'))) AND NOT EXISTS(SELECT 1 FROM json_each(json_extract((SELECT body FROM nba_bootstrap_events WHERE event='manifest:'||NEW.run AND kind='manifest'),'$.versions')) j WHERE v.source=json_extract(j.value,'$.source') AND v.sha=json_extract(j.value,'$.sha') AND v.body=json_extract(j.value,'$.body') AND v.bytes=json_extract(j.value,'$.bytes'))) OR EXISTS(SELECT 1 FROM json_each(json_extract((SELECT body FROM nba_bootstrap_events WHERE event='manifest:'||NEW.run AND kind='manifest'),'$.beforeChecks')) j WHERE NOT EXISTS(SELECT 1 FROM nba_history_checks c WHERE c.source=json_extract(j.value,'$.source') AND c.sha=json_extract(j.value,'$.sha') AND c.verified=json_extract(j.value,'$.verified'))) OR EXISTS(SELECT 1 FROM nba_history_checks c WHERE c.source IN(SELECT value FROM json_each(json_extract((SELECT body FROM nba_bootstrap_events WHERE event='manifest:'||NEW.run AND kind='manifest'),'$.sources'))) AND NOT EXISTS(SELECT 1 FROM json_each(json_extract((SELECT body FROM nba_bootstrap_events WHERE event='manifest:'||NEW.run AND kind='manifest'),'$.beforeChecks')) j WHERE c.source=json_extract(j.value,'$.source') AND c.sha=json_extract(j.value,'$.sha') AND c.verified=json_extract(j.value,'$.verified'))) THEN RAISE(ABORT,'bootstrap_atomic_publish_conflict') END;
 END;

CREATE TRIGGER IF NOT EXISTS nba_bootstrap_publish_apply AFTER INSERT ON nba_bootstrap_events WHEN NEW.kind='publish' BEGIN
 INSERT INTO nba_history_checks(source,sha,verified) SELECT json_extract(j.value,'$.source'),json_extract(j.value,'$.sha'),json_extract(j.value,'$.verified') FROM json_each(json_extract((SELECT body FROM nba_bootstrap_events WHERE event='manifest:'||NEW.run AND kind='manifest'),'$.newChecks')) j;
 END;

CREATE TRIGGER IF NOT EXISTS nba_bootstrap_rollback_guard BEFORE INSERT ON nba_bootstrap_events WHEN NEW.kind='rollback' BEGIN
 SELECT CASE WHEN NEW.event!='rollback:'||NEW.run OR NEW.body!='{}' OR (SELECT body FROM nba_bootstrap_events WHERE event='manifest:'||NEW.run AND kind='manifest') IS NULL OR NOT EXISTS(SELECT 1 FROM nba_bootstrap_events WHERE event='publish:'||NEW.run AND kind='publish') OR EXISTS(SELECT 1 FROM nba_bootstrap_events WHERE run=NEW.run AND kind='consume') THEN RAISE(ABORT,'bootstrap_rollback_invalid_or_consumed') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM json_each(json_extract((SELECT body FROM nba_bootstrap_events WHERE event='manifest:'||NEW.run AND kind='manifest'),'$.versions')) j WHERE NOT EXISTS(SELECT 1 FROM nba_history_versions v WHERE v.source=json_extract(j.value,'$.source') AND v.sha=json_extract(j.value,'$.sha') AND v.body=json_extract(j.value,'$.body') AND v.bytes=json_extract(j.value,'$.bytes'))) OR EXISTS(SELECT 1 FROM nba_history_versions v WHERE v.source IN(SELECT value FROM json_each(json_extract((SELECT body FROM nba_bootstrap_events WHERE event='manifest:'||NEW.run AND kind='manifest'),'$.sources'))) AND NOT EXISTS(SELECT 1 FROM json_each(json_extract((SELECT body FROM nba_bootstrap_events WHERE event='manifest:'||NEW.run AND kind='manifest'),'$.versions')) j WHERE v.source=json_extract(j.value,'$.source') AND v.sha=json_extract(j.value,'$.sha') AND v.body=json_extract(j.value,'$.body') AND v.bytes=json_extract(j.value,'$.bytes'))) OR EXISTS(SELECT 1 FROM json_each(json_extract((SELECT body FROM nba_bootstrap_events WHERE event='manifest:'||NEW.run AND kind='manifest'),'$.newChecks')) j WHERE NOT EXISTS(SELECT 1 FROM nba_history_checks c WHERE c.source=json_extract(j.value,'$.source') AND c.sha=json_extract(j.value,'$.sha') AND c.verified=json_extract(j.value,'$.verified'))) OR EXISTS(SELECT 1 FROM json_each(json_extract((SELECT body FROM nba_bootstrap_events WHERE event='manifest:'||NEW.run AND kind='manifest'),'$.beforeChecks')) j WHERE NOT EXISTS(SELECT 1 FROM nba_history_checks c WHERE c.source=json_extract(j.value,'$.source') AND c.sha=json_extract(j.value,'$.sha') AND c.verified=json_extract(j.value,'$.verified'))) OR EXISTS(SELECT 1 FROM nba_history_checks c WHERE c.source IN(SELECT value FROM json_each(json_extract((SELECT body FROM nba_bootstrap_events WHERE event='manifest:'||NEW.run AND kind='manifest'),'$.sources'))) AND NOT EXISTS(SELECT 1 FROM json_each(json_extract((SELECT body FROM nba_bootstrap_events WHERE event='manifest:'||NEW.run AND kind='manifest'),'$.newChecks')) j WHERE c.source=json_extract(j.value,'$.source') AND c.sha=json_extract(j.value,'$.sha') AND c.verified=json_extract(j.value,'$.verified')) AND NOT EXISTS(SELECT 1 FROM json_each(json_extract((SELECT body FROM nba_bootstrap_events WHERE event='manifest:'||NEW.run AND kind='manifest'),'$.beforeChecks')) j WHERE c.source=json_extract(j.value,'$.source') AND c.sha=json_extract(j.value,'$.sha') AND c.verified=json_extract(j.value,'$.verified'))) THEN RAISE(ABORT,'bootstrap_rollback_later_evidence') END;
 END;

CREATE TRIGGER IF NOT EXISTS nba_bootstrap_rollback_apply AFTER INSERT ON nba_bootstrap_events WHEN NEW.kind='rollback' BEGIN
 DELETE FROM nba_history_checks WHERE EXISTS(SELECT 1 FROM json_each(json_extract((SELECT body FROM nba_bootstrap_events WHERE event='manifest:'||NEW.run AND kind='manifest'),'$.newChecks')) j WHERE nba_history_checks.source=json_extract(j.value,'$.source') AND nba_history_checks.sha=json_extract(j.value,'$.sha') AND nba_history_checks.verified=json_extract(j.value,'$.verified'));
 END;

CREATE TRIGGER IF NOT EXISTS nba_bootstrap_consume_guard BEFORE INSERT ON nba_bootstrap_events WHEN NEW.kind='consume' BEGIN SELECT CASE WHEN NEW.event!='consume:'||NEW.run OR NEW.body!='{}' OR NOT EXISTS(SELECT 1 FROM nba_bootstrap_events WHERE event='publish:'||NEW.run) OR EXISTS(SELECT 1 FROM nba_bootstrap_events WHERE event='rollback:'||NEW.run) THEN RAISE(ABORT,'bootstrap_consume_invalid') END; END;
